import java.io.*;
import java.util.*;

public class CutletVariant1 {
    static int n, k, lo, hi;
    static int[][] segs;
    static int[] l, delt;
    static int[][][] dp;
    static ArrayList<int[]> finSeg = new ArrayList<>();

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        segs = new int[k][2];

        for (int i = 0; i < k; i++) {
            st = new StringTokenizer(br.readLine());
            segs[i][0] = Integer.parseInt(st.nextToken());
            segs[i][1] = Integer.parseInt(st.nextToken());
        }

        Arrays.sort(segs, (a, b) -> a[0] - b[0]);

        int i = 0;
        while (i < k) {
            lo = segs[i][0];
            hi = segs[i][0];
            int j = i;
            while (j < k && segs[j][0] <= hi) {
                hi = Math.max(hi, segs[j][1]);
                j++;
            }
            finSeg.add(new int[]{lo, hi});
            i = j;
        }

        k = finSeg.size();
        segs = new int[k][2];
        l = new int[k];
        delt = new int[k];

        for (int idx = 0; idx < k; idx++) {
            segs[idx] = finSeg.get(idx);
        }

        for (int idx = 0; idx < k; idx++) {
            l[idx] = segs[idx][1] - segs[idx][0];
            if (idx < k - 1) {
                delt[idx] = segs[idx + 1][0] - segs[idx][1];
            } else {
                delt[idx] = 2 * n - segs[idx][1];
            }
        }

        dp = new int[2][k + 1][2 * n + 1];
        for (int[] layer : dp) {
            for (int[] row : layer) {
                Arrays.fill(row, n);
            }
        }

        dp[0][k][n] = 0;
        dp[1][k][n] = 0;

        RMQ[] rmq = {new RMQ(dp[0][k]), new RMQ(dp[1][k])};

        for (int idx = k - 1; idx >= 0; idx--) {
            for (int j = 0; j <= 2 * n; j++) {
                int val0 = (j + l[idx] + delt[idx] <= 2 * n) ? dp[0][idx + 1][j + l[idx] + delt[idx]] : n;
                int val1 = dp[1][idx + 1][j];

                dp[0][idx][j] = Math.min(val0, 1 + rmq[1].min(j, Math.min(j + l[idx], 2 * n)));
                if (j + delt[idx] <= 2 * n) {
                    int candidate1 = 1 + rmq[0].min(j + delt[idx], Math.min(j + l[idx] + delt[idx], 2 * n));
                    dp[1][idx][j] = Math.min(val1, candidate1);
                } else {
                    dp[1][idx][j] = val1;
                }

                if (j + delt[idx] <= 2 * n) {
                    int candidate2 = 2 + rmq[0].min(j + delt[idx], Math.min(j + l[idx] + delt[idx], 2 * n));
                    dp[0][idx][j] = Math.min(dp[0][idx][j], candidate2);
                }

                int candidate3 = 2 + rmq[1].min(j, Math.min(j + l[idx], 2 * n));
                dp[1][idx][j] = Math.min(dp[1][idx][j], candidate3);
            }
            rmq[0] = new RMQ(dp[0][idx]);
            rmq[1] = new RMQ(dp[1][idx]);
        }

        int ans = dp[1][0][0];
        if (ans == n) {
            System.out.println("Hungry");
        } else {
            System.out.println("Full");
            System.out.println(ans);
        }
    }

    static class RMQ {
        int n, k;
        int[][] min;

        public RMQ(int[] a) {
            n = a.length;
            k = Integer.numberOfTrailingZeros(Integer.highestOneBit(n)) + 1;
            min = new int[k][n];
            System.arraycopy(a, 0, min[0], 0, n);
            for (int i = 1; i < k; i++) {
                for (int j = 0; j + (1 << (i - 1)) < n; j++) {
                    min[i][j] = Math.min(min[i - 1][j], min[i - 1][j + (1 << (i - 1))]);
                }
            }
        }

        public int min(int a, int b) {
            int z = Integer.numberOfTrailingZeros(Integer.highestOneBit(b - a + 1));
            return Math.min(min[z][a], min[z][b - (1 << z) + 1]);
        }
    }
}
