#include <bits/stdc++.h>
using namespace std;

int n, k, lo, hi;
vector<vector<int>> segs;
vector<int> l, delt;
vector<vector<vector<int>>> dp;
vector<vector<int>> finSeg;

struct RMQ {
    int n, k;
    vector<vector<int>> min;

    RMQ(const vector<int>& a) {
        n = a.size();
        k = __builtin_ctzll((1ULL << 31) | n) + 1;
        min.assign(k, vector<int>(n));
        for (int i = 0; i < n; i++) {
            min[0][i] = a[i];
        }
        for (int i = 1; i < k; i++) {
            for (int j = 0; j + (1 << (i - 1)) < n; j++) {
                min[i][j] = std::min(min[i - 1][j], min[i - 1][j + (1 << (i - 1))]);
            }
        }
    }

    int min_query(int a, int b) {
        int z = __builtin_ctzll((1ULL << 31) | (b - a + 1));
        return std::min(min[z][a], min[z][b - (1 << z) + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k;
    segs.assign(k, vector<int>(2));
    for (int i = 0; i < k; i++) {
        cin >> segs[i][0] >> segs[i][1];
    }
    sort(segs.begin(), segs.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[0] < b[0];
    });
    int i = 0;
    while (i < k) {
        lo = segs[i][0];
        hi = segs[i][0];
        int j = i;
        while (j < k && segs[j][0] <= hi) {
            hi = max(hi, segs[j][1]);
            j++;
        }
        finSeg.push_back({lo, hi});
        i = j;
    }
    k = (int)finSeg.size();
    segs.assign(k, vector<int>(2));
    l.assign(k, 0);
    delt.assign(k, 0);
    for (int idx = 0; idx < k; idx++) {
        segs[idx] = finSeg[idx];
    }
    for (int idx = 0; idx < k; idx++) {
        l[idx] = segs[idx][1] - segs[idx][0];
        if (idx < k - 1) {
            delt[idx] = segs[idx + 1][0] - segs[idx][1];
        } else {
            delt[idx] = 2 * n - segs[idx][1];
        }
    }
    dp.assign(2, vector<vector<int>>(k + 1, vector<int>(2 * n + 1, n)));
    for (int j = 0; j <= 2 * n; j++) {
        dp[0][k][j] = 0;
        dp[1][k][j] = 0;
    }
    vector<RMQ> rmq = {RMQ(dp[0][k]), RMQ(dp[1][k])};
    for (int idx = k - 1; idx >= 0; idx--) {
        for (int j = 0; j <= 2 * n; j++) {
            int val0 = (j + l[idx] + delt[idx] <= 2 * n) ? dp[0][idx + 1][j + l[idx] + delt[idx]] : n;
            int val1 = dp[1][idx + 1][j];

            int min1 = (j + l[idx] + delt[idx] <= 2 * n) ? rmq[1].min_query(j, min(j + l[idx], 2 * n)) : n;
            dp[0][idx][j] = min(val0, 1 + min1);

            if (j + delt[idx] <= 2 * n) {
                int candidate1 = 1 + rmq[0].min_query(j + delt[idx], min(j + l[idx] + delt[idx], 2 * n));
                dp[1][idx][j] = min(val1, candidate1);
            } else {
                dp[1][idx][j] = val1;
            }

            if (j + delt[idx] <= 2 * n) {
                int candidate2 = 2 + rmq[0].min_query(j + delt[idx], min(j + l[idx] + delt[idx], 2 * n));
                dp[0][idx][j] = min(dp[0][idx][j], candidate2);
            }

            int candidate3 = 2 + rmq[1].min_query(j, min(j + l[idx], 2 * n));
            dp[1][idx][j] = min(dp[1][idx][j], candidate3);
        }
        rmq[0] = RMQ(dp[0][idx]);
        rmq[1] = RMQ(dp[1][idx]);
    }
    int ans = dp[1][0][0];
    if (ans == n) {
        cout << "Hungry\n";
    } else {
        cout << "Full\n" << ans << "\n";
    }
    return 0;
}

